package service

import (
	"encoding/json"
	"errors"
	"os"
	"strings"
	"testing"

	"github.com/carbogninalberto/assozeta/BE_GO/internal/mentions"
	"github.com/carbogninalberto/assozeta/BE_GO/internal/pystr"
)

// mentionsOtherGolden is testdata/mentions_other.json, generated by
// testdata/gen_mentions_other.py from BE/application/models/utils.py's
// get_nested_attr: the str() of other.<key>.<attribute...> for a sample str
// value, with the address of a live object replaced by pystr.ObjectAddress.
type mentionsOtherGolden struct {
	Python      string            `json:"python"`
	Placeholder string            `json:"placeholder"`
	Other       map[string]string `json:"other"`
	Cases       []struct {
		Key   string `json:"key"`
		Value string `json:"value"`
	} `json:"cases"`
}

func readMentionsOtherGolden(t *testing.T) mentionsOtherGolden {
	t.Helper()
	data, err := os.ReadFile("testdata/mentions_other.json")
	if err != nil {
		t.Fatal(err)
	}
	var golden mentionsOtherGolden
	if err := json.Unmarshal(data, &golden); err != nil {
		t.Fatal(err)
	}
	if golden.Placeholder != pystr.ObjectAddress {
		t.Fatalf("golden placeholder %q, pystr.ObjectAddress %q", golden.Placeholder, pystr.ObjectAddress)
	}
	if len(golden.Cases) == 0 {
		t.Fatal("golden has no cases")
	}
	return golden
}

// TestOtherResolverGolden compares otherResolver with get_nested_attr of the
// reference Python for every name in dir(str), the attributes of a built-in
// method, a method-wrapper and the str type, and paths through None.
func TestOtherResolverGolden(t *testing.T) {
	golden := readMentionsOtherGolden(t)
	resolve := otherResolver(golden.Other)
	for _, item := range golden.Cases {
		path := strings.TrimPrefix(item.Key, "other.")
		got, err := resolve(path)
		if err != nil {
			t.Errorf("%s: %v", item.Key, err)
			continue
		}
		if got != item.Value {
			t.Errorf("%s:\nwant %q\n got %q", item.Key, item.Value, got)
		}
	}
}

// TestOtherResolverRefusals is the part of the str object graph the port does
// not reproduce: a type object's __dict__ (a mappingproxy of addresses) and
// the numbers that depend on the CPython build, and a method object's own
// dunder methods (the port stops at the metadata a method carries). Each is
// mentions.ErrUnsupported, so the view hands the request to Django.
func TestOtherResolverRefusals(t *testing.T) {
	resolve := otherResolver(map[string]string{"today": "16/11/2026"})
	for _, path := range []string{
		"today.__class__.__dict__",
		"today.__class__.__flags__",
		"today.__class__.__basicsize__",
		"today.__class__.__itemsize__",
		"today.__class__.__weakrefoffset__",
		"today.__class__.__dictoffset__",
		"today.upper.__call__",
		"today.__add__.__eq__",
		"today.__class__.upper.__get__",
		"today.upper.__class__.mro",
	} {
		if value, err := resolve(path); !errors.Is(err, mentions.ErrUnsupported) {
			t.Errorf("%s: %q, %v, want ErrUnsupported", path, value, err)
		}
	}
}

// TestOtherResolverMentionFormatting is _format_mention_value over the raw
// str() the resolver answers: it strips the value and rewrites a
// YYYY-MM-DD shaped one as DD/MM/YYYY. bs4 escapes the markup characters of
// a text node, as str(soup) does in Django.
func TestOtherResolverMentionFormatting(t *testing.T) {
	cases := []struct{ value, want string }{
		{"16/11/2026", "16/11/2026"},
		{" 2026-11-16 ", "16/11/2026"},
		{" Pilates ", "Pilates"},
		{"<built-in method upper of str object at 0x7f0000000000>",
			"&lt;built-in method upper of str object at 0x7f0000000000&gt;"},
	}
	for _, item := range cases {
		html := `<p><span class="mention" data-type="mention" key="other.today">x</span></p>`
		got, err := mentions.Filter(html, true, mentions.Context{"other": otherResolver(map[string]string{"today": item.value})})
		if err != nil {
			t.Errorf("%q: %v", item.value, err)
			continue
		}
		if want := "<p>" + item.want + "</p>"; got != want {
			t.Errorf("%q: %q, want %q", item.value, got, want)
		}
	}
}
